import glob, re
roots = ["schemas/skill.schema.json", "schemas/litmus.schema.json", "schemas/research.schema.json", "schemas/egress-log.schema.json"]
loads = []
for f in glob.glob("**/*.py", recursive=True) + glob.glob("**/*.sh", recursive=True):
    if f.startswith(".git") or "/out/" in f: continue
    for line in open(f, errors="ignore").read().splitlines():
        for r in roots:
            if r in line and re.search(r"open\(|load\(|read_text|cat ", line):
                loads.append((f, r))
print("the 4 repo-root schemas exist; code sites that load any of them: %d" % len(loads))
PY
